INSERT INTO answers (id, contradiction_id, answer, answer_explanation, created_at) VALUES (45, 21, 'Yes, God has a body.', 'And they heard the voice of the LORD God walking in the garden in the cool of the day. 
				      Genesis 3:8', '2026-01-28 21:21:36');
INSERT INTO answers (id, contradiction_id, answer, answer_explanation, created_at) VALUES (46, 21, 'No, God is a bodyless spirit.', 'God is a spirit. John 4:24
				
