INSERT INTO answers (id, contradiction_id, answer, answer_explanation, created_at) VALUES (167, 77, 'Yes', 'I will bless thee, and in multiplying I will multiply thy seed as the stars of the heaven, and as the sand which is upon the sea shore; and thy seed shall possess the gate of his enemies; 
