INSERT INTO answers (id, contradiction_id, answer, answer_explanation, created_at) VALUES (185, 85, 'And Anah was also the son of Zibeon.', 'The sons of Zibeon; Aiah, and Anah. 1 Chronicles 1:40', '2026-01-28 21:21:36');
INSERT INTO answers (id, contradiction_id, answer, answer_explanation, created_at) VALUES (186, 86, 'Esau was Korah''s father.', 'And Aholibamah bare Jeush, and Jaalam, and Korah: these are the sons of Esau, 
