INSERT INTO answers (id, contradiction_id, answer, answer_explanation, created_at) VALUES (196, 91, 'Yes, Mahli was Levi''s son.', '... of the sons of Mahli, the son of Levi, the son of Israel.... Ezra 8:18', '2026-01-28 21:21:36');
INSERT INTO answers (id, contradiction_id, answer, answer_explanation, created_at) VALUES (197, 91, 'No.', 'And the sons of Levi; Gershon, Kohath, and Merari. Genesis 46:11, 
				      1 Chronicles 6:1, 16
				        
